"""Physical handling, bounded refunds/default recovery and no false deliveries."""
from test_mobile_rendering import ROOT,html
from playwright.sync_api import sync_playwright
import json,hashlib
source=(ROOT/'assets/game.js').read_text();sha=hashlib.sha256(source.encode()).hexdigest()
probe=r'''
window.__logisticsTest=()=>{__townTest.reset('settlement',42);G.autoBuild=false;const total=totalMoney(),f=G.firms.find(f=>f.kind==='grocer'),market=OUTSIDE_MARKETS[0],s=ensureRegionalTrade();s.routePreference='interchange';G.policy.importTariff=20;
 const advance=(id,limit=60)=>{const history=[];for(let i=0;i<limit&&s.shipments.some(o=>o.id===id);i++){G.day++;regionalFreightDay();const o=s.shipments.find(o=>o.id===id);history.push(o?.stage||'settled')}return history};
 const cash=f.cash,stock=f.stock.food;dispatchRegional(f,'food',60,'import',regionalQuote(f,market,'food','import'));const early=s.shipments.at(-1),fee=early.freight;cancelRegionalShipment(early.id);G.day++;regionalFreightDay();if(s.shipments.some(o=>o.id===early.id)||Math.abs(f.cash-(cash-fee))>.001||f.stock.food!==stock)throw Error('Early refund/stock incorrect');
 dispatchRegional(f,'food',60,'import',regionalQuote(f,market,'food','import'));const late=s.shipments.at(-1);while(late.stage!=='outside'){G.day++;regionalFreightDay()}cancelRegionalShipment(late.id);const history=advance(late.id);if(f.stock.food!==stock||!history.includes('return-outside'))throw Error('Late cancelled cargo became usable or skipped return travel');
 dispatchRegional(f,'food',60,'import',regionalQuote(f,market,'food','import'));const refund=s.shipments.at(-1);cancelRegionalShipment(refund.id);const shifted=G.region;G.treasury+=shifted;G.region=0;G.day++;regionalFreightDay();if(!s.claims.length||s.shipments.some(o=>o.id===refund.id))throw Error('Unfunded refund minted cash or blocked cargo pool');G.treasury-=shifted;G.region+=shifted;G.day++;regionalFreightDay();if(s.claims.length)throw Error('Refund did not clear when funded');
 dispatchRegional(f,'food',60,'import',regionalQuote(f,market,'food','import'));const incoming=s.shipments.at(-1);const delivered=advance(incoming.id);if(f.stock.food<stock+59.999||!delivered.includes('delivering'))throw Error('Paid import skipped physical last mile');
 const farm=G.firms.find(f=>formulas[f.kind]?.out==='grain'),farmStock=farm.stock.grain;dispatchRegional(farm,'grain',5,'export',regionalQuote(farm,market,'grain','export'));const recalled=s.shipments.at(-1);cancelRegionalShipment(recalled.id);advance(recalled.id);if(Math.abs(farm.stock.grain-farmStock)>.001)throw Error('Recalled export did not return owned inventory');
 const bank=G.banks.find(b=>!b.closed&&b.cash>5000),ownerCash=G.households[farm.owner]?.cash||0;bank.cash-=5000;farm.cash+=5000;farm.debt=(farm.debt||0)+5000;const loan={id:++G.nextLoanId,ownerType:'firm',ownerId:farm.id,bankId:bank.id,balance:5000,original:5000,paid:0,rate:.05,term:360,status:'active',arrears:100};G.loans.push(loan);G.region+=farm.cash;farm.cash=0;dispatchRegional(farm,'grain',5,'export',regionalQuote(farm,market,'grain','export'));/* Fund only the actual carrier charge for the controlled estate shipment. */if(!s.shipments.some(o=>o.firm===farm.id)){const grant=10;G.region-=grant;farm.cash+=grant;dispatchRegional(farm,'grain',5,'export',regionalQuote(farm,market,'grain','export'));G.region+=farm.cash;farm.cash=0;}const estate=s.shipments.at(-1);liquidateFirm(farm,'controlled funded-creditor default');const bankBefore=bank.cash;advance(estate.id);if(!(bank.cash>bankBefore)||Math.abs((G.households[farm.owner]?.cash||0)-ownerCash)>.001)throw Error('Estate recovery skipped defaulted creditor');
 if(Math.abs(totalMoney()-total)>.001)throw Error('Cash was created/lost');if(Math.max(...goodsBalance().map(x=>Math.abs(x.error)))>.001)throw Error('Commodity ledger lost in-transit or returned title');return{history,delivered,claims:s.claims.length,deliveredCount:s.delivered,cancelled:s.cancelled,cashDrift:totalMoney()-total,goods:goodsBalance(),valid:validateTown()};};
'''
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page(viewport={'width':844,'height':390});errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(html);p.add_script_tag(content=source.replace('// SOURCE: 99-instrumentation.js',probe+'\n// SOURCE: 99-instrumentation.js'));p.locator('#newTown').click();p.locator('#pause').click();r=p.evaluate('__logisticsTest()');assert r['valid']['ok'],r;saved=p.evaluate('__townTest.save()');assert p.evaluate('s=>__townTest.load(s)',saved);bad=json.loads(saved);bad['regionalTrade']['claims']=[{'firm':0,'regional':-1,'treasury':0,'estateOwner':None,'created':1}];assert not p.evaluate('s=>__townTest.load(s)',json.dumps(bad));assert not errors,errors;b.close()
assert hashlib.sha256((ROOT/'assets/game.js').read_bytes()).hexdigest()==sha
out=ROOT/'reports/development-8.0';(out/'logistics.json').write_text(json.dumps({'source_sha256':sha,'result':r,'errors':errors},indent=2)+'\n');print('PASS physical staging, early/late refunds, unfunded receivable recovery, last mile, export recall, cash/goods, archive atomicity',r)
